[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <file:///github/workspace/portolan-reference> ;
            sh:resultMessage "the rel 'icon' link has no title to use as its accessible label (PORTO-CORE-076)" ;
            sh:resultSeverity sh:Warning ;
            sh:sourceConstraint [ a sh:SPARQLConstraint ;
                    sh:message "the rel 'icon' link has no title to use as its accessible label (PORTO-CORE-076)" ;
                    sh:select """
            SELECT $this ?value WHERE {
                $this <http://www.w3.org/2000/01/rdf-schema#seeAlso> ?value .
                ?value <http://www.iana.org/assignments/relation> <http://www.iana.org/assignments/relation/icon> .
                FILTER NOT EXISTS { ?value <http://www.w3.org/2000/01/rdf-schema#label> ?title }
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape ptl:IconLinkHasTitleShape ;
            sh:value [ dct:type "image/png" ;
                    ns1:relation <http://www.iana.org/assignments/relation/icon> ;
                    ns2:hasTarget <file:///github/workspace/_assets/portolan-logo.png> ] ] .

